H.line(TL[0], baseY-h-14, TR[0], baseY-h-14, {color:H.colors.violet, width:1.5});
H.text("b2 = " + b2.toFixed(0), cx, baseY-h-28, {color:H.colors.violet, size:13, align:"center"});
